CREATE TABLE IF NOT EXISTS households (id INTEGER PRIMARY KEY AUTOINCREMENT, kk_number TEXT NOT NULL UNIQUE, address TEXT NOT NULL, rt TEXT, rw TEXT, head_resident_id INTEGER REFERENCES resident_profiles(id) ON DELETE SET NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS household_members (id INTEGER PRIMARY KEY AUTOINCREMENT, household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, resident_id INTEGER NOT NULL UNIQUE REFERENCES resident_profiles(id) ON DELETE CASCADE, relationship TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS business_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS resident_businesses (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL REFERENCES resident_profiles(id), category_id INTEGER NOT NULL REFERENCES business_categories(id), name TEXT NOT NULL, description TEXT, whatsapp TEXT, whatsapp_public INTEGER DEFAULT 0, address TEXT, photo_url TEXT, latitude REAL, longitude REAL, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS village_locations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT, latitude REAL NOT NULL, longitude REAL NOT NULL, is_public INTEGER DEFAULT 1);
